+          payload: {
+            role: "system",
+            text: "Codex reconnect complete."
+          }
+        });
       } catch (error) {
         this.connected = false;
         this.sendSessionState();
         this.emitError("reconnect_failed", (error as Error).message, true);
         await this.handleDisconnect();
       }
     }
```

*Only one line added* (`this.reconnectAttempts = 0;`) – no new state, no new public API, no timing changes.

### 3️⃣ Why this satisfies the extra constraint  

* **Guard stays hard** – `maxReconnectAttempts` is still `5`. The guard (`if (this.reconnectAttempts > runtimeConfig.maxReconnectAttempts)`) is unchanged.  
* **Counter is cleared only on success** – the reset occurs **after** the successful `restart`/`thread/resume`/`refreshModelCatalog` sequence and **before** the “reconnect complete” message is emitted.  
* **No other code path touches `reconnectAttempts`** – the only other place that increments it is `handleDisconnect()`, which runs only on a *new* disconnect. Therefore the guard will fire only after **five consecutive** disconnects, exactly as the original design intended.

